      open(parser, strm, filename)
      while readRow(parser):
        for col in parser.row:
            echo col.split(",")
      close(parser)

  # We just convert both to string to avoid math operations on `Time` and `DateTime`
  echo "Elapsed: Done at ", now().utc()

when isMainModule:
  processCSV("/tmp", "data.csv")
